// features/lifecycle.feature: An admin can review vendors
import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("an admin can open the review queue and approve a vendor's w9 extraction", { tag: "@LIF-12" }, async ({ apiAs, factory }) => {
    // Arrange
    const { vendor, documents, extractions } = await factory.vendorInReview();
    const admin = await apiAs("admin");

    // Act
    const queueResponse = await admin.get("/api/review-queue");
    const queue = await expectStatus<{ vendor_id: string; vendor_name: string; extractions: { id: string }[] }[]>(queueResponse, 200);
    const decisionResponse = await admin.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    const item = queue.find((q) => q.vendor_id === vendor.id);
    expect(item, `review queue lists vendor ${vendor.name}`).toBeDefined();
    expect(item?.vendor_name).toBe(vendor.name);
    expect(item?.extractions.map((e) => e.id)).toContain(extractions.w9.id);
    const decided = await expectStatus<{ id: string; status: string }>(decisionResponse, 200);
    expect(decided.status).toBe("approved");
    const stored = await factory.extraction(documents.w9.id, "admin");
    expect(stored.status).toBe("approved");
  });
});
